g.script:
/**/
(function() {
  var stage = document.getElementById('a16p4-stage');
  var btnBoth = document.getElementById('a16p4-btn-both');
  var btnMs = document.getElementById('a16p4-btn-ms');
  var btnFebrasgo = document.getElementById('a16p4-btn-febrasgo');
  var pillsTrigger = document.getElementById('a16p4-pills-trigger');

  var tooltipBg = document.getElementById('a16p4-tooltip-bg');
  var tooltipTitle = document.getElementById('a16p4-tooltip-title');
  var tooltipBody1 = document.getElementById('a16p4-tooltip-body1');
  var tooltipBody2 = document.getElementById('a16p4-tooltip-body2');

  function setMode(mode) {
    stage.setAttribute('data-mode', mode);

    btnBoth.classList.remove('a16p4-active');
    btnMs.classList.remove('a16p4-active');
    btnFebrasgo.classList.remove('a16p4-active');

    if (mode === 'both') btnBoth.classList.add('a16p4-active');
    if (mode === 'ms') btnMs.classList.add('a16p4-active');
    if (mode === 'febrasgo') btnFebrasgo.classList.add('a16p4-active');

    hideTooltip();
  }

  function showTooltip(title, line1, line2) {
    tooltipTitle.textContent = title;
    tooltipBody1.textContent = line1;
    tooltipBody2.textContent = line2;

    tooltipBg.classList.add('a16p4-visible');
    tooltipTitle.setAttribute('opacity', '1');
    tooltipBody1.setAttribute('opacity', '1');
    tooltipBody2.setAttribute('opacity', '1');
  }

  function hideTooltip() {
    tooltipBg.classList.remove('a16p4-visible');
    tooltipTitle.setAttribute('opacity', '0');
    tooltipBody1.setAttribute('opacity', '0');
    tooltipBody2.setAttribute('opacity', '0');
  }

  if (btnBoth) btnBoth.addEventListener('click', function() { setMode('both'); });
  if (btnMs) btnMs.addEventListener('click', function() { setMode('ms'); });
  if (btnFebrasgo) btnFebrasgo.addEventListener('click', function() { setMode('febrasgo'); });

  if (pillsTrigger) {
    pillsTrigger.addEventListener('click', function(e) {
      e.stopPropagation();
      if (tooltipBg.classList.contains('a16p4-visible')) {
        hideTooltip();
      } else {
        showTooltip(
          "💡 DETALHE FARMACODINÂMICO DO CARBONATO DE CÁLCIO (MS):",
          "Cada comprimido de 1.250 mg de Carbonato de Cálcio fornece 500 mg de Cálcio Elementar.",
          "Portanto, 2 comprimidos fornecem exatamente a dose recomendada de 1.000 mg (1 g) de cálcio elementar."
        );
      }
    });
  }

  document.addEventListener('click', function(e) {
    if (pillsTrigger && e.target !== pillsTrigger && !pillsTrigger.contains(e.target)) {
      hideTooltip();
    }
  });
})();
/**/
